const D = { density:.5, scale:1, hue:205, energy:.6, speed:1, iso:.5, x:.5, y:.5, style:'chrome', act:'orbit', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2, frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H);
const dens=clp(P.density,0,1), en=clp(P.energy,0,1), sc=clp(P.scale,0,2.4);
const style=P.style, hueP=((P.hue%360)+360)%360;
const cx=P.x*W, cy=P.y*H, t=K.t*clp(P.speed,0,4);

const NB=Math.max(2, Math.round(2+dens*7));
if(S.nb!==NB || S.seedUsed!==P.seed){
  S.seedUsed=P.seed; S.nb=NB; S.blobs=[];
  for(let i=0;i<NB;i++) S.blobs.push({
    ph:fr(i*3.1)*TAU, sp:.16+fr(i*5.7)*.5, orb:.12+fr(i*7.3)*.3,
    rr:.06+fr(i*9.1)*.075, wob:fr(i*11.7)*TAU, lane:fr(i*13.3) });
}

let bgH,bgS,bgB;
if(style==='thermal'){bgH=245;bgS=55;bgB=6;}
else if(style==='blueprint'){bgH=214;bgS=68;bgB=17;}
else if(style==='xray'){bgH=205;bgS=35;bgB=8;}
else if(style==='oil'){bgH=255;bgS=45;bgB=8;}
else {bgH=208;bgS=22;bgB=11;}
const bkey=W+'x'+H+'|'+style+'|'+P.seed;
if(S.bgKey!==bkey){
  S.bgKey=bkey;
  const g=createGraphics(W,H); g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  g.fill(bgH,bgS,bgB); g.rect(0,0,W,H);
  for(let r=0;r<26;r++){ g.fill(bgH,bgS,Math.max(2,bgB-r*0.42),7); g.ellipse(W/2,H/2, W*(1.55-r*0.032), H*(1.55-r*0.032)); }
  for(let i=0;i<1500;i++){ const gx=fr(i*1.7)*W,gy=fr(i*2.3)*H; g.fill(bgH,bgS*.5,bgB+(fr(i*3.1)-.5)*12,13); g.rect(gx,gy,1.6,1.6); }
  S.bg=g;
}
image(S.bg,0,0);

const bass=A.bass||0, treb=A.treble||0, swell=K.swell, pulse=K.pulse;
const pos=[];
for(let i=0;i<NB;i++){
  const b=S.blobs[i], wob=Math.sin(t*b.sp*2+b.wob)*.02; let bx,by;
  if(P.act==='lava'){
    const yy=frc(t*b.sp*.22+b.lane); by=cy+(yy-.5)*H*.92; bx=cx+Math.sin(t*b.sp+b.ph)*u*b.orb*.5;
  } else if(P.act==='swarm'){
    bx=cx+(Math.sin(t*b.sp+b.ph)+Math.sin(t*b.sp*1.7+b.wob)*.6)*u*b.orb;
    by=cy+(Math.cos(t*b.sp*1.3+b.ph)+Math.cos(t*b.sp*.9+b.wob)*.6)*u*b.orb;
  } else {
    const orb=b.orb*(1-bass*.34); bx=cx+Math.cos(t*b.sp+b.ph)*u*orb; by=cy+Math.sin(t*b.sp*1.11+b.ph)*u*orb;
  }
  const br=(b.rr+wob)*u*sc*(1+en*.3*pulse+bass*.4);
  pos.push({x:bx,y:by,r2:br*br});
}

const cell=Math.max(14,u/16), cols=Math.ceil(W/cell), rows=Math.ceil(H/cell), nx=cols+1;
if(!S.val || S.gk!==W+'x'+H+'|'+cols+'|'+rows){ S.gk=W+'x'+H+'|'+cols+'|'+rows; S.val=new Float32Array((cols+1)*(rows+1)); }
const val=S.val, dx=W/cols, dy=H/rows;
for(let j=0;j<=rows;j++){ const py=j*dy; for(let i=0;i<=cols;i++){ const px=i*dx; let f=0;
  for(let m=0;m<NB;m++){ const p=pos[m], ex=px-p.x, ey=py-p.y; f+=p.r2/(ex*ex+ey*ey+80); } val[j*nx+i]=f; } }

const isoT=(0.55+clp(P.iso,0,1)*0.9)*(1-0.18*swell);
const lineStyle=(style==='xray'||style==='blueprint');

if(lineStyle){ noFill();
  if(style==='blueprint'){ stroke(196,78,90,82); strokeWeight(Math.max(1,u*0.0026)); }
  else { blendMode(ADD); stroke(hueP,45,96,60); strokeWeight(Math.max(1.5,u*0.006)); }
} else noStroke();

const shade=(fx,fy,fv)=>{
  if(style==='thermal'){ const h=clp((fv-isoT)/(isoT*1.5),0,1); return [250-h*250, 100-h*48, 26+h*72]; }
  if(style==='oil'){ const band=frc(fv*0.05+fy*0.004+t*0.05); return [(hueP+band*360)%360, 55, 44+34*Math.sin(band*TAU)]; }
  const band=Math.sin(fv*0.05+fy*0.02+t*0.6+fx*0.004); return [hueP, 12+8*Math.abs(band), 44+42*band];
};

for(let j=0;j<rows;j++) for(let i=0;i<cols;i++){
  const x0=i*dx,x1=(i+1)*dx,y0=j*dy,y1=(j+1)*dy;
  const a=val[j*nx+i], b=val[j*nx+i+1], c=val[(j+1)*nx+i+1], d=val[(j+1)*nx+i];
  const inA=a>=isoT,inB=b>=isoT,inC=c>=isoT,inD=d>=isoT;
  const nin=(inA?1:0)+(inB?1:0)+(inC?1:0)+(inD?1:0);
  if(nin===0) continue;
  const cxs=[x0,x1,x1,x0], cys=[y0,y0,y1,y1], cvs=[a,b,c,d], cin=[inA,inB,inC,inD];
  if(lineStyle){ const pts=[];
    for(let e=0;e<4;e++){ const n=(e+1)%4; if(cin[e]!==cin[n]){ const tI=(isoT-cvs[e])/(cvs[n]-cvs[e]); pts.push([cxs[e]+(cxs[n]-cxs[e])*tI, cys[e]+(cys[n]-cys[e])*tI]); } }
    if(pts.length>=2) line(pts[0][0],pts[0][1],pts[1][0],pts[1][1]);
    if(pts.length>=4) line(pts[2][0],pts[2][1],pts[3][0],pts[3][1]);
    continue;
  }
  const poly=[];
  for(let e=0;e<4;e++){ const n=(e+1)%4; if(cin[e]) poly.push([cxs[e],cys[e]]);
    if(cin[e]!==cin[n]){ const tI=(isoT-cvs[e])/(cvs[n]-cvs[e]); poly.push([cxs[e]+(cxs[n]-cxs[e])*tI, cys[e]+(cys[n]-cys[e])*tI]); } }
  if(poly.length>=3){ const col=shade((x0+x1)*.5,(y0+y1)*.5,(a+b+c+d)*.25);
    fill(col[0],col[1],col[2]); beginShape(); for(let q=0;q<poly.length;q++) vertex(poly[q][0],poly[q][1]); endShape(CLOSE); }
}

if(!lineStyle && (treb>0.05)){ blendMode(ADD); noStroke();
  for(let i=0;i<NB;i++){ const p=pos[i]; fill(0,0,100,18*treb); ellipse(p.x-Math.sqrt(p.r2)*.3, p.y-Math.sqrt(p.r2)*.3, u*0.02*sc); } }

blendMode(BLEND); drawingContext.shadowBlur=0;
